// 1️⃣ Extract raw LLM JSON string
const rawText = item.json.output?.[0]?.content?.[0]?.text;

if (!rawText) {
  throw new Error("LLM output not found in expected structure.");
}

// 2️⃣ Parse LLM output safely
let llmData;

try {
  llmData = JSON.parse(rawText);
} catch (e) {
  throw new Error("Failed to parse LLM JSON output");
}

// 3️⃣ Get original article metadata
const {
  title = "Unknown Title",
  description = "",
  source = null,
  url = null,
  published_at = null
} = item.json;

// 4️⃣ Extract LLM sentiment fields
const {
  short_term_score,
  long_term_score,
  confidence,
  primary_driver,
  direction
} = llmData;

// ---- 5️⃣ Score Band Mapping ----
function getBand(score) {
  if (score <= 0.2) return "strong_bearish";
  if (score <= 0.4) return "mild_bearish";
  if (score <= 0.55) return "neutral";
  if (score <= 0.7) return "mild_bullish";
  return "strong_bullish";
}

const short_band = getBand(short_term_score);
const long_band = getBand(long_term_score);

// ---- 6️⃣ Structural Flag ----
const structuralDrivers = [
  "REGULATION_POSITIVE",
  "REGULATION_NEGATIVE",
  "ETF_FLOWS",
  "MONETARY_POLICY",
  "MACRO_LIQUIDITY",
  "INSTITUTIONAL_ADOPTION"
];

const structural_flag = structuralDrivers.includes(primary_driver);

// ---- 7️⃣ Liquidity Flag ----
const liquidityDrivers = [
  "ETF_FLOWS",
  "MACRO_LIQUIDITY",
  "MONETARY_POLICY"
];

const liquidity_flag = liquidityDrivers.includes(primary_driver);

// ---- 8️⃣ Deterministic Embedding Text ----
const vector_text = `
CRYPTO MARKET SENTIMENT SNAPSHOT

Title: ${title}

Primary Driver: ${primary_driver}
Short Term Direction: ${direction}
Short Term Score Band: ${short_band}
Long Term Score Band: ${long_band}
Confidence Level: ${confidence}
Structural Impact: ${structural_flag}
Liquidity Relevant: ${liquidity_flag}

Article Context:
${description || "No description provided."}
`.trim();

// ---- 9️⃣ Flat Payload (Qdrant optimized) ----
const payload = {
  title,
  source,
  url,
  published_at,
  primary_driver,
  direction,
  short_term_score,
  long_term_score,
  short_term_band: short_band,
  long_term_band: long_band,
  confidence,
  structural_flag,
  liquidity_flag
};

// ---- 🔟 Stable Deterministic ID ----

// Clean URL (remove tracking & consent redirects)
function cleanUrl(rawUrl) {
  if (!rawUrl) return null;

  if (rawUrl.includes("consent.yahoo.com")) return null;

  try {
    const urlObj = new URL(rawUrl);
    urlObj.search = ""; // remove tracking parameters
    return urlObj.toString();
  } catch (e) {
    return rawUrl;
  }
}

// Simple deterministic hash function
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0;
  }
  return Math.abs(hash).toString();
}

const cleanedUrl = cleanUrl(url);

// Prefer cleaned URL for ID, fallback to title + date
const stableId = cleanedUrl
  ? hashString(cleanedUrl)
  : hashString((title || "") + (published_at || ""));

// ---- 11️⃣ Return Qdrant-ready object ----
return {
  json: {
    id: stableId,
    vector_text,
    payload
  }
};

if (items.length === 0) {
  throw new Error("No sentiment items received for aggregation.");
}

// ---- 1️⃣ Aggregate ----
let shortSum = 0;
let longSum = 0;

let bullish = 0;
let bearish = 0;
let neutral = 0;

const driverCount = {};
const confidenceCount = { low: 0, moderate: 0, high: 0 };

for (const item of items) {
  const p = item.json.payload;

  shortSum += p.short_term_score;
  longSum += p.long_term_score;

  if (p.direction === "bullish") bullish++;
  else if (p.direction === "bearish") bearish++;
  else neutral++;

  driverCount[p.primary_driver] =
    (driverCount[p.primary_driver] || 0) + 1;

  confidenceCount[p.confidence] =
    (confidenceCount[p.confidence] || 0) + 1;
}

const count = items.length;

const short_term_avg = parseFloat((shortSum / count).toFixed(4));
const long_term_avg = parseFloat((longSum / count).toFixed(4));
const divergence = parseFloat(
  Math.abs(short_term_avg - long_term_avg).toFixed(4)
);

// ---- 2️⃣ Score → Band Text ----
function band(score) {
  if (score <= 0.2) return "strong_bearish";
  if (score <= 0.4) return "mild_bearish";
  if (score <= 0.55) return "neutral";
  if (score <= 0.7) return "mild_bullish";
  return "strong_bullish";
}

const short_band = band(short_term_avg);
const long_band = band(long_term_avg);

// ---- 3️⃣ Dominant Driver ----
let dominant_driver = null;
let maxDriverCount = 0;

for (const driver in driverCount) {
  if (driverCount[driver] > maxDriverCount) {
    dominant_driver = driver;
    maxDriverCount = driverCount[driver];
  }
}

// ---- 4️⃣ Aggregate Confidence ----
let final_confidence = "low";

if (confidenceCount.high > count * 0.5) {
  final_confidence = "high";
} else if (
  confidenceCount.moderate + confidenceCount.high >
  count * 0.5
) {
  final_confidence = "moderate";
}

// ---- 5️⃣ Regime Label ----
function regimeBand(score) {
  if (score <= 0.4) return "neg";
  if (score >= 0.6) return "pos";
  return "neu";
}

const regime = `Short_${regimeBand(short_term_avg)}_Long_${regimeBand(long_term_avg)}`;

// ---- 6️⃣ Return Clean Sentiment Snapshot ----
return [
  {
    json: {
      sentiment_snapshot: {
        article_count: count,
        short_term_avg,
        long_term_avg,
        short_term_band: short_band,
        long_term_band: long_band,
        divergence,
        bullish_count: bullish,
        bearish_count: bearish,
        neutral_count: neutral,
        dominant_driver,
        regime,
        confidence: final_confidence
      }
    }
  }
];
